mapper.update:
UPDATE board
SET board_view_count = NVL(board_view_count,0) + 1
WHERE board_id = #{boardId}

UPDATE board
SET board_title = #{title},
    board_content = #{content},
    board_update = SYSTIMESTAMP,
    is_anonymous_yn = #{isAnonymousYn}
WHERE board_id = #{boardId}
  AND member_id = #{memberId}
  AND board_delete_fl = 'N'

UPDATE board
SET board_delete_fl = 'Y',
    board_update = SYSTIMESTAMP
WHERE board_id = #{boardId}
  AND member_id = #{memberId}
  AND board_delete_fl = 'N'

