INSERT INTO board_image(
  image_id, board_id, image_url, sort_order, create_date
)
VALUES(
  SEQ_IMAGE.NEXTVAL, #{boardId}, #{imageUrl}, #{sortOrder}, SYSTIMESTAMP
)

