UPDATE board_comment
SET comment_content = #{content},
    update_date = SYSTIMESTAMP
WHERE comment_id = #{commentId}
  AND member_id = #{memberId}
  AND delete_fl = 'N'

UPDATE board_comment
SET delete_fl = 'Y',
    update_date = SYSTIMESTAMP
WHERE comment_id = #{commentId}
  AND member_id = #{memberId}
  AND delete_fl = 'N'
